"""Actual append-only journal IO, independent reload and corruption rejection."""
from pathlib import Path
import hashlib,json,subprocess,tempfile
ROOT=Path(__file__).resolve().parents[1];work=ROOT/'work/qqmusic-journal';work.mkdir(exist_ok=True)
(work/'report.json').unlink(missing_ok=True)
core=['runtime/apps/qqmusic/qqmusic_'+n+'.c' for n in ('journal','volume','storage','asset','source','output','directory','stage','stage_volume','protocol','session')]+['runtime/store/https_url.c','runtime/native/sha256.c','tools/fixtures/qqmusic_journal.c']
flags=['-std=c99','-Wall','-Wextra','-Werror','-Wl,--wrap=open,--wrap=open64,--wrap=readlink,--wrap=lstat,--wrap=__lxstat64']
host=work/'journal-tests.sanitized';subprocess.run(['gcc-12',*flags,'-O1','-g','-fsanitize=address,undefined',*core,'-o',str(host)],cwd=ROOT,check=True)
with tempfile.TemporaryDirectory(prefix='host-',dir=work) as directory:subprocess.run([str(host),directory],cwd=ROOT,check=True,timeout=30);assert not list(Path(directory).iterdir())
lib=ROOT/'work/arm-signal-tests/lib'
for name,digest in {'libc.so.6':'5afbf3074dfa9ba0478d6670f220ef4d7ec065a255ee856d9093d39210f23812','ld-linux.so.3':'2f007b0809684fde0ac446ad203135c10b4318eb8c10d4160a9f59b32c3c52de'}.items():assert hashlib.sha256((lib/name).read_bytes()).hexdigest()==digest
arm=work/'journal-tests.arm'
subprocess.run(['arm-linux-gnueabi-gcc',*flags,'-Os','-DHB_STORE_SONY_LIBC','-march=armv5te','-marm','-mfloat-abi=soft','-ffreestanding','-fno-builtin','-fno-pie','-nostdlib','-no-pie','-Wl,--hash-style=sysv','-Wl,--build-id=none','-Wl,--dynamic-linker=/lib/ld-linux.so.3',*core,'runtime/store/stock_fs_bridge.c','runtime/store/stock_stat64.c','runtime/store/stock_tls_compat.c','runtime/store/start.c','runtime/store/start.S',str(lib/'libc.so.6'),str(lib/'ld-linux.so.3'),'-lgcc','-o',str(arm)],cwd=ROOT,check=True)
with tempfile.TemporaryDirectory(prefix='arm-',dir=work) as directory:subprocess.run(['qemu-arm','-cpu','arm926',str(lib/'ld-linux.so.3'),'--library-path',str(lib),str(arm),directory],cwd=ROOT,check=True,timeout=30);assert not list(Path(directory).iterdir())
report={'passed':True,'scope':'native_append_only_user_volume_journal','device_tested':False,'actual_file_io':True,'fixture_mount_mapping':True,'checks':['exclusive create preserves collision','five ordered records reload independently','explicit endian/length and chained hash','resource identity and filename binding','immutable paths and known content digests','illegal stage jumps and terminal append reject','outside user path rejects before create','trailing byte after published returns review','corrupt initial payload exposes no record','truncated terminal exposes only verified prefix','readonly mount poisons writer without append retry','symlink and traversal reject','bounded read-only directory catalog','malformed journal entry reported without actions','catalog limit reports partial result','no journal truncation, deletion or repair by module'],'arm_sha256':hashlib.sha256(arm.read_bytes()).hexdigest(),'sources':{p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in core+['runtime/apps/qqmusic/qqmusic_journal.h','runtime/apps/qqmusic/qqmusic_job_record.h','tools/fixtures/qqmusic_volume.c']},'limits':['Record values are synthetic; source/MP3 files are not generated in this journal unit test.','No actual Sony FAT or power-loss qualification.','Read-only classification only, no automatic recovery or file actions.']}
(work/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({k:v for k,v in report.items() if k!='sources'},indent=2))
